"""Observability, monitoring and telemetry query practice."""
from ._catalog import build_guided_catalog, build_lessons

CATEGORIES = [
    {"id": "signals", "title": "Signals & Instrumentation", "color": "sky", "blurb": "Metrics, logs, traces, OpenTelemetry and SLOs."},
    {"id": "prometheus", "title": "Prometheus & PromQL", "color": "mint", "blurb": "Scrapes, labels, queries, recording rules and alert rules."},
    {"id": "grafana", "title": "Grafana Dashboards & Alerts", "color": "peach", "blurb": "Panels, variables, transformations, alerting and provisioning."},
    {"id": "logs", "title": "Logstash, Elasticsearch & Kibana", "color": "lilac", "blurb": "Parse, index, search and retain operational logs."},
    {"id": "tracing", "title": "Jaeger & Distributed Tracing", "color": "rose", "blurb": "Propagate context, inspect spans and find latency bottlenecks."},
]

TOPICS = build_lessons([
    ("obs-signals", "Metrics, Logs & Traces: the Three Signals", "signals", "basic", "Metrics summarize numeric behavior over time, logs record discrete events, and traces show one request crossing service boundaries. Correlate them with stable service, environment, version and trace identifiers.", "Request → trace spans → structured logs → RED metrics", "Start from a user-visible symptom, use metrics to scope impact, traces to locate latency, and logs to inspect the failing operation.", "Which signal best answers whether the whole service is getting slower?", "A latency metric shows the aggregate trend and affected scope; traces locate slow dependencies, and logs explain individual failures.", ["obs-instrumentation", "obs-slos"]),
    ("obs-instrumentation", "Instrument Services with OpenTelemetry", "signals", "intermediate", "OpenTelemetry APIs and SDKs create vendor-neutral metrics, logs and traces; the Collector receives, processes and exports telemetry. Use semantic conventions and resource attributes consistently.", "OTEL_SERVICE_NAME=checkout · exporter → Collector → Prometheus / Jaeger", "Keep instrumentation vendor-neutral; set service.name, deployment.environment and service.version once at process startup.", "Why send telemetry through an OpenTelemetry Collector?", "It centralizes batching, filtering, redaction, sampling and exporter configuration so applications are less coupled to backend vendors.", ["obs-signals", "obs-traces"]),
    ("obs-slos", "SLIs, SLOs & Error Budgets", "signals", "advanced", "An SLI measures a user-relevant outcome such as successful request ratio or latency under a threshold. An SLO sets its target over a window; the error budget is the allowed unreliability and guides release risk.", "Good events / eligible events over a rolling 30-day window", "Alert on fast error-budget burn and define the user journey, window, exclusions and owner before choosing a target.", "Why can a CPU alert be less useful than an SLO burn alert?", "CPU is a cause signal and may be harmless. Error-budget burn directly indicates that users are experiencing failures or unacceptable latency against the reliability target.", ["obs-signals", "prom-alerting"]),
    ("prom-scrape-model", "Prometheus Targets, Scrapes & Exporters", "prometheus", "basic", "Prometheus periodically scrapes HTTP exposition endpoints and stores samples with metric names and labels. Exporters expose metrics for systems that do not have native instrumentation; service discovery updates targets dynamically.", "GET /metrics → scrape interval → time series samples", "Check target health, scrape duration, sample limits and relabeling before diagnosing a missing metric.", "A target is UP but a dashboard metric is absent. What do you check?", "Inspect the endpoint payload, scrape configuration, metric name, relabel rules, labels and time range; UP only confirms the scrape succeeded.", ["obs-promql", "obs-cardinality"]),
    ("obs-labels", "Metric Labels & Cardinality", "prometheus", "intermediate", "Each distinct label set creates a time series. Labels should be bounded dimensions such as method, status class or region; user IDs, raw URLs and request IDs create unbounded cardinality.", "http_requests_total{service=\"checkout\",method=\"POST\",code=\"500\"}", "Keep per-request identifiers in traces or logs, never metric labels; monitor head series and ingestion growth.", "Why is user_id a dangerous Prometheus label?", "Every user creates another series for every metric and label combination, consuming memory and query capacity and often causing explosive cardinality.", ["promql-rate", "obs-promql"]),
    ("obs-promql", "PromQL Selectors, Matchers & Aggregation", "prometheus", "basic", "PromQL selects instant or range vectors by metric name and label matchers, then filters and aggregates series. Use `sum by (...)` to preserve only dimensions needed for the question.", "sum by (service) (http_requests_total{code=~\"5..\"})", "Start with a raw selector, inspect labels, then aggregate; avoid accidentally summing different units or incompatible series.", "How would you count 5xx requests by service?", "Use `sum by (service) (http_requests_total{code=~\"5..\"})`, after confirming the counter and label names in the target Prometheus.", ["promql-rate", "promql-histogram"]),
    ("promql-rate", "PromQL for Rates, Errors & RED Dashboards", "prometheus", "intermediate", "For counters, apply `rate(counter[window])` before aggregation so resets are handled per series. RED dashboards show request rate, error ratio and duration for each service.", "sum by (service) (rate(http_requests_total[5m]))", "Choose a window long enough to contain several scrapes; compute ratios with clamped denominators and preserve service labels.", "Write a query for the fraction of requests returning 5xx in five minutes.", "Use `sum(rate(http_requests_total{code=~\"5..\"}[5m])) / clamp_min(sum(rate(http_requests_total[5m])), 1e-9)`; add `by (service)` to both sides when comparing each service.", ["obs-promql", "prom-alerting"]),
    ("promql-histogram", "Histograms, Buckets & p95 Latency Queries", "prometheus", "advanced", "Classic Prometheus histograms export cumulative `_bucket` counters, `_sum` and `_count`. Estimate a quantile with `histogram_quantile` after applying `rate` and aggregating buckets while retaining `le`.", "histogram_quantile(0.95, sum by (service, le) (rate(http_request_duration_seconds_bucket[5m])))", "Never average per-instance p95 values; aggregate histogram buckets first, and verify bucket boundaries cover your SLO threshold.", "Why must the `le` label remain in a classic histogram query?", "It identifies each cumulative bucket boundary; histogram_quantile needs the bucket distribution to estimate the requested quantile.", ["promql-rate", "grafana-panels"]),
    ("prom-recording-rules", "Prometheus Recording Rules", "prometheus", "intermediate", "Recording rules precompute frequently used expressions into new time series. They reduce dashboard query cost and provide a shared, reviewed definition for ratios and service-level indicators.", "record: service:http_requests:rate5m\nexpr: sum by (service) (rate(http_requests_total[5m]))", "Use clear metric naming, bounded labels and evaluation groups; validate rule files with promtool before loading.", "When should a team add a recording rule?", "When a costly expression is reused widely or needs a stable shared SLI; avoid recording every exploratory query and multiplying storage unnecessarily.", ["promql-rate", "prom-alerting"]),
    ("prom-alerting", "Prometheus Alert Rules & PromQL", "prometheus", "intermediate", "Alert rules evaluate PromQL and fire when a condition remains true for a `for` duration. Labels route alerts; annotations explain impact and link to a runbook. Alertmanager groups, deduplicates, silences and routes notifications.", "alert: HighErrorRate\nexpr: service_error_ratio > 0.02\nfor: 10m", "Alert on actionable symptoms, set a meaningful pending duration, include service and severity labels, and test with promtool.", "What belongs in an alert annotation versus a label?", "Labels carry bounded routing and grouping dimensions such as team and severity; annotations carry human-readable summary, impact and runbook URL.", ["prom-recording-rules", "grafana-alerts"]),
    ("prom-alertmanager", "Alertmanager Routing, Grouping & Silences", "prometheus", "advanced", "Alertmanager routes alerts by labels to receivers, groups related firing alerts, inhibits dependent alerts and supports time-bounded silences. It handles notification policy, while Prometheus evaluates alert expressions.", "route by team → group by alertname, cluster → pager or ticket receiver", "Keep routes explicit, test notification templates and set silence expiry; do not silence an entire service indefinitely to hide noise.", "Prometheus shows a firing alert but nobody receives a page. What do you inspect?", "Check Alertmanager target connectivity, route matchers, receiver configuration, inhibition, grouping wait, active silences and delivery errors.", ["prom-alerting", "grafana-alerts"]),
    ("grafana-datasources", "Grafana Data Sources & Provisioning", "grafana", "basic", "Grafana connects dashboards to data sources such as Prometheus, Elasticsearch and Jaeger. Provision data sources and dashboards from version-controlled files for repeatable environments.", "Provision Prometheus URL, auth, TLS and default data source", "Use service accounts and least privilege; do not put credentials in dashboard JSON or browser-visible variables.", "Why provision dashboards rather than editing only in the UI?", "Provisioning makes changes reviewable, reproducible and consistent across environments, while avoiding lost configuration during rebuilds.", ["grafana-panels", "grafana-variables"]),
    ("grafana-panels", "Grafana Panels, Units & Thresholds", "grafana", "basic", "A panel combines a query with a visualization, unit, legend and thresholds. Select time series for trends, stat panels for current values, tables for discrete rows and heatmaps for distributions.", "Panel: p95 latency · unit seconds · threshold at the SLO objective", "Name units and legends explicitly; choose a panel that matches the data semantics and make bad states visually obvious.", "A latency graph shows 250 but users do not know if that means milliseconds or seconds. What fixes it?", "Set the correct unit in the panel and make the query return values in that unit; use a clear title and legend.", ["grafana-datasources", "grafana-variables"]),
    ("grafana-variables", "Grafana Variables, Templating & Drilldowns", "grafana", "intermediate", "Variables let a dashboard select cluster, namespace, service or environment and reuse the choice in panel queries. Chained variables narrow options; data links take users from a metric to related logs or traces.", "$service → rate(http_requests_total{service=~\"$service\"}[5m])", "Use multi-value-safe regex matchers, sensible defaults and bounded variable queries; avoid variables that enumerate millions of values.", "Why use `=~` for a multi-select Grafana variable?", "Multi-select variables expand to a regular expression matching the selected values; `=` would treat that expanded expression as one literal value.", ["grafana-panels", "grafana-dashboards"]),
    ("grafana-dashboards", "Designing Operational Grafana Dashboards", "grafana", "intermediate", "A useful service dashboard starts with traffic, errors, latency and saturation, then gives links to dependencies, logs, traces, deployment markers and runbooks. Shared filters should align across rows.", "Overview row → RED → saturation → dependency panels → links and annotations", "Put high-signal user impact first, preserve units, use a consistent time range and keep panels focused on decisions.", "What should an on-call engineer see first on a service dashboard?", "Whether users are affected: request rate, error ratio and latency against the SLO, with service/region filters and direct links to traces, logs and runbooks.", ["grafana-panels", "obs-slos"]),
    ("grafana-alerts", "Grafana Alert Rules & Contact Points", "grafana", "intermediate", "Grafana-managed alerts evaluate queries and expressions, pending periods and labels, then route notifications through contact points and notification policies. Keep ownership and runbooks attached to alert definitions.", "Query A error ratio → threshold expression B → pending 5m → route by team", "Prevent duplicate alert definitions across Grafana and Prometheus unless ownership and deduplication are deliberate.", "An alert fires on every brief traffic dip. How do you tune it?", "Check whether zero traffic is a valid condition, use a pending period or no-data policy, add a traffic-aware denominator, and alert only when user impact is meaningful.", ["prom-alerting", "grafana-dashboards"]),
    ("log-pipeline", "ELK Stack: Elasticsearch, Logstash & Kibana", "logs", "basic", "The ELK stack combines Elasticsearch for indexed search and aggregations, Logstash for ingest pipelines, and Kibana for exploration and dashboards. Beats or agents commonly ship events into the pipeline.", "Application JSON → shipper → Logstash → Elasticsearch data stream → Kibana", "Use structured JSON at the source and define timestamp, service, environment and severity fields consistently.", "What does each ELK component do?", "Logstash parses and routes events, Elasticsearch stores and indexes searchable documents, and Kibana searches and visualizes the indexed data.", ["logstash-pipeline", "kibana-kql"]),
    ("logstash-pipeline", "Write Logstash Input, Filter & Output Pipelines", "logs", "intermediate", "A Logstash pipeline has inputs, filters and outputs. Inputs receive beats, files or queues; filters parse, enrich, mutate or redact; outputs send events to Elasticsearch or another destination.", "input { beats { port => 5044 } } → filter { json { source => \"message\" } } → elasticsearch { index => \"logs-%{+YYYY.MM.dd}\" }", "Test representative good, malformed and sensitive events; use pipeline-to-pipeline flow and dead-letter handling when appropriate.", "A Logstash event is indexed but all fields stay inside `message`. What do you add?", "Parse the payload with the correct codec or a JSON/Grok filter, verify the source field, inspect tags such as `_grokparsefailure`, and test the event in a staging pipeline.", ["log-grok", "elasticsearch-mappings"]),
    ("log-grok", "Grok Patterns, Dissect & Parse Failures", "logs", "intermediate", "Grok extracts named fields from irregular text using patterns; Dissect efficiently splits consistently delimited messages. Parse failures should be tagged, monitored and routed for inspection rather than silently discarded.", "%{TIMESTAMP_ISO8601:timestamp} %{LOGLEVEL:level} %{DATA:service} - %{GREEDYDATA:message}", "Prefer JSON or Dissect for stable formats; anchor Grok patterns and prevent expensive backtracking on untrusted input.", "How do you find events that failed a Grok parse?", "Search for the `_grokparsefailure` tag, inspect the original message and sample variants, then add a tested pattern or route malformed records to a quarantine index.", ["logstash-pipeline", "kibana-kql"]),
    ("elasticsearch-mappings", "Elasticsearch Mappings, Data Streams & ILM", "logs", "intermediate", "Mappings define field types and analyzers; data streams organize append-only time-series documents behind a write alias. Index Lifecycle Management rolls, shrinks and deletes indices by age or size.", "Map `@timestamp` as date, status as integer, service as keyword; retain hot data 7d and delete at policy end", "Set mappings before production ingestion, separate keyword from analyzed text, and align retention with legal and incident-response needs.", "A Kibana range query misses documents even though the text is present. What mapping issue might cause this?", "The timestamp may be mapped as text instead of date, or a field may be analyzed when exact matching is needed; inspect the mapping and query the correct keyword/date field.", ["log-pipeline", "kibana-kql"]),
    ("kibana-kql", "Kibana KQL: Write Precise Log Queries", "logs", "basic", "Kibana Query Language filters documents with field-value expressions. Combine clauses with AND/OR/NOT, quote strings with spaces, and use field existence and ranges to narrow a time-bounded search.", "service.name: \"checkout\" and log.level: error and http.response.status_code >= 500", "Set the correct data view and time range first; prefer exact keyword fields for IDs, service names and status values.", "Write a query for checkout errors with HTTP status 500 or higher.", "`service.name: \"checkout\" and log.level: error and http.response.status_code >= 500`; field names depend on the pipeline mapping and ECS version.", ["log-grok", "kibana-discover"]),
    ("kibana-discover", "Kibana Discover, Filters & Aggregations", "logs", "intermediate", "Discover is for searching and inspecting individual events; Lens or dashboards aggregate trends by fields. Filter by exact service, environment, error code and time range before inspecting representative documents.", "Filter errors → histogram by 5m → top services → inspect sample trace_id", "Avoid broad wildcard queries on large indices; use aggregations for trends and document inspection for examples.", "How do you find the most frequent exception type during a deploy window?", "Filter to the deploy time range and service, require error severity, aggregate by the mapped exception type, then inspect example documents and correlate by version or trace ID.", ["kibana-kql", "log-pipeline"]),
    ("obs-traces", "Distributed Tracing: Spans, Parents & Context", "tracing", "basic", "A trace is a tree of spans representing work across processes. Propagate W3C Trace Context so services join spans into one request; span attributes and events explain operations without high-cardinality metrics.", "traceparent header → API span → database and queue child spans", "Instrument inbound/outbound boundaries, preserve trace context through async messaging and avoid putting secrets or personal data in span attributes.", "A request appears as separate traces in two services. What is commonly broken?", "Trace context is not being propagated or extracted across the HTTP, RPC or messaging boundary, so the downstream span starts a new trace.", ["jaeger-search", "obs-instrumentation"]),
    ("jaeger-search", "Jaeger: Search Traces & Find Latency", "tracing", "intermediate", "Jaeger receives and stores trace data and lets engineers search by service, operation, tags, duration and time. The trace waterfall reveals serial waits, fan-out, retries and dependency latency.", "Search service=checkout, operation=POST /orders, min duration=1s", "Start with a slow or failed trace, compare sibling requests and inspect the longest critical-path spans and their tags.", "A Jaeger trace is slow, but no one span is very slow. What might explain it?", "Sequential moderate waits can add up; inspect parent-child timing, retry spans, queue delay and whether calls are serial rather than parallel.", ["obs-traces", "obs-tail-sampling"]),
    ("obs-tail-sampling", "Trace Sampling & Retention", "tracing", "advanced", "Sampling controls trace volume. Head sampling decides early with limited request context; tail sampling waits for completion and can retain errors or slow traces. Storage retention balances incident value, privacy and cost.", "Keep 100% errors and slow traces; sample a small fraction of healthy requests", "Ensure sampling decisions are consistent across services and budget collector memory for the longest in-flight traces.", "Why use tail sampling for a rare intermittent error?", "The Collector can inspect the completed trace and retain it based on error status or latency, whereas head sampling may discard it before the outcome is known.", ["jaeger-search", "obs-instrumentation"]),
    ("obs-telemetry-triage", "Telemetry Triage: Metrics to Logs to Traces", "signals", "advanced", "Triage starts with time, service, environment and impact. Use a metric to find when and where behavior changed, a trace to locate the slow or failing hop, and structured logs to inspect its concrete error and request context.", "Alert fingerprint → dashboard window → trace_id → Kibana event → deploy marker", "Keep clocks synchronized and service/version/trace identifiers consistent; redact sensitive values at collection and storage boundaries.", "Error rate rose after a deploy, while only one dependency is slow. What sequence isolates the cause?", "Filter the error-rate panel by service and version, inspect representative traces for the dependency span, then query logs by trace ID and compare with the deploy marker.", ["obs-signals", "grafana-dashboards", "jaeger-search"]),
], "OBS", "Telemetry is a trail of evidence: define the question, write a bounded query, and connect the result to an owner and runbook.")

TOPICS += build_guided_catalog([
    ("prom-http-metrics", "Expose Application Metrics", "prometheus", "basic", "Instrument request counters, duration histograms and in-progress gauges at service boundaries; use the Prometheus client library and expose a protected metrics endpoint.", "Counter: http_requests_total{method,route,status}; Histogram: http_request_duration_seconds", "Which metric type should represent total requests?", "A counter, because request totals only increase and can be converted to a per-second rate with PromQL. Do not use a gauge for a monotonically increasing event count.", ["prom-scrape-model"]),
    ("prom-gauge-counter", "Choose Counters, Gauges & Histograms", "prometheus", "basic", "Counters measure cumulative events, gauges represent a value that rises and falls, and histograms record distributions into buckets. Choose based on the measured quantity rather than the desired chart.", "Queue depth → gauge; completed jobs → counter; request duration → histogram", "How should queue depth be instrumented?", "As a gauge that is set to the current number of queued items; it can increase and decrease as work arrives and completes.", ["prom-http-metrics", "promql-histogram"]),
    ("prom-target-relabel", "Relabel Targets & Scraped Metrics", "prometheus", "advanced", "Relabeling can select, drop or rewrite targets before scraping and can transform labels after scraping. Keep labels useful and bounded, and distinguish target relabeling from metric relabeling.", "Keep only targets with __meta_kubernetes_namespace=payments; drop debug_* series", "When do you use metric_relabel_configs?", "After a scrape, to drop or rewrite sample labels or metrics before ingestion; target relabeling instead controls which scrape targets and labels Prometheus uses.", ["prom-scrape-model", "obs-labels"]),
    ("prom-service-discovery", "Prometheus Service Discovery", "prometheus", "intermediate", "Service discovery keeps scrape targets current as infrastructure changes. Kubernetes, cloud and file-based discovery expose metadata that relabeling can turn into stable job and service labels.", "kubernetes_sd_configs role: endpoints; relabel namespace, service and port", "A new pod is not scraped; which discovery details should you inspect?", "Check discovery configuration, namespace and label selectors, endpoint readiness, relabel keep/drop rules and the generated target list in Prometheus service-discovery UI.", ["prom-scrape-model", "prom-target-relabel"]),
    ("prom-scrape-interval", "Scrape Intervals, Timeouts & Staleness", "prometheus", "intermediate", "Scrape interval, timeout and evaluation interval determine resolution and load. A timeout must be shorter than the interval; stale markers and missed scrapes affect query gaps and alert behavior.", "scrape_interval: 30s · scrape_timeout: 10s · evaluation_interval: 30s", "What happens when scrape_timeout exceeds scrape_interval?", "Prometheus rejects the invalid configuration; the timeout must not exceed the scrape interval. Keep enough headroom for endpoint response and scrape load.", ["prom-scrape-model", "prom-alerting"]),
    ("prom-promtool", "Validate Prometheus Rules with promtool", "prometheus", "intermediate", "promtool checks Prometheus configuration, syntax and rule files, and can run deterministic rule tests from fixtures. Run it in CI so malformed alerts do not reach production.", "promtool check config prometheus.yml && promtool test rules rules_test.yml", "Why add promtool test rules to CI?", "It catches invalid expressions and verifies alert behavior against known sample series before rule changes are deployed.", ["prom-recording-rules", "prom-alerting"]),
    ("prom-absent-up", "Detect Missing Targets with up and absent()", "prometheus", "intermediate", "The `up` series indicates whether a known target scrape succeeded. `absent()` can detect a series that disappeared entirely, but it needs stable selectors and careful expected-target logic.", "up{job=\"api\"} == 0 · absent_over_time(up{job=\"api\"}[10m])", "Why may an alert on `up == 0` miss a service that vanished from discovery?", "If the target disappears, there may be no `up` series to equal zero. Use absent() or an expected-target metric and ensure the selector identifies what should exist.", ["prom-service-discovery", "prom-alerting"]),
    ("prom-joins", "PromQL Vector Matching & Joins", "prometheus", "advanced", "PromQL can match vectors by shared labels and use `on`, `ignoring`, `group_left` or `group_right` for one-to-many relationships. Reduce both sides to the intended key before joining.", "rate(container_cpu_seconds_total[5m]) / on(pod) group_left sum by(pod)(kube_pod_container_resource_limits)", "A vector expression reports many-to-many matching. What should you change?", "Aggregate each side to a unique set of matching labels or correct `on`/`ignoring` keys; only use group modifiers when the relationship is intentionally one-to-many.", ["obs-promql", "promql-rate"]),
    ("prom-joins-bool", "PromQL Comparisons, bool & Clamp Functions", "prometheus", "intermediate", "PromQL comparisons filter vector elements by default; `bool` returns 0/1 values. Clamp functions bound values and can protect ratios from zero denominators, but should not hide missing traffic.", "(error_rate / clamp_min(request_rate, 1e-9)) > 0.02", "Why can a zero-denominator guard create a misleading error ratio?", "It can turn no traffic into an artificial value or mask missing telemetry. Pair the ratio with an explicit traffic/no-data condition and document its behavior.", ["promql-rate", "prom-alerting"]),
    ("prom-subqueries", "PromQL Subqueries & Long-Window Trends", "prometheus", "advanced", "Subqueries evaluate an expression over a range at a chosen resolution. They help analyze smoothed rates or rolling quantiles, but can be expensive; use a recording rule for repeated heavy expressions.", "max_over_time((sum(rate(http_requests_total[5m])))[1h:1m])", "When should a repeated subquery become a recording rule?", "When it is used frequently on dashboards or alerts and a stable precomputed series reduces query latency and backend load.", ["prom-recording-rules", "promql-rate"]),
    ("prom-native-histograms", "Native Histograms & Quantile Tradeoffs", "prometheus", "advanced", "Native histograms store bucket distributions in a compact sample and can support aggregation across compatible schemas. Verify scrape, storage and query support across the full Prometheus and remote-write path.", "histogram_quantile(0.99, sum by(service)(rate(request_duration_seconds[5m])))", "What should be tested before migrating classic histograms?", "Confirm client exposition, Prometheus feature support, remote storage compatibility, query semantics and recording/alert rules with production-shaped data.", ["promql-histogram", "prom-scrape-model"]),
    ("prom-federation", "Prometheus Federation & Remote Write", "prometheus", "advanced", "Federation scrapes selected aggregate time series from another Prometheus; remote write streams samples to a compatible receiver. Both patterns need explicit label ownership, backpressure, retention and failure monitoring.", "Federate only service-level recording rules; remote-write selected tenant metrics", "Why avoid federating every raw series into a global Prometheus?", "It multiplies cardinality and makes the global tier expensive. Federation should export useful aggregates and preserve clear cluster and tenant labels.", ["prom-recording-rules", "obs-cardinality"]),
    ("grafana-transformations", "Grafana Transformations & Query Expressions", "grafana", "intermediate", "Transformations reshape returned data for display, while data-source queries perform the underlying selection and aggregation. Prefer source-side aggregation for large datasets and use transformations for presentation joins.", "Join a deploy annotation table to a latency time series by time", "A dashboard panel is slow because it downloads millions of raw rows. What is the fix?", "Aggregate and filter at the data source, set a suitable query interval and time range, and avoid using browser transformations as a substitute for efficient queries.", ["grafana-panels", "grafana-dashboards"]),
    ("grafana-annotations", "Grafana Annotations & Deploy Markers", "grafana", "basic", "Annotations mark releases, incidents, configuration changes or maintenance windows on time-series panels. Correlating a metric shift with a deploy provides temporal evidence, not proof of causation.", "Annotate deploy revision, environment and actor at rollout start", "What metadata makes a deploy annotation useful?", "Include service, environment, version or commit, timestamp and a link to the change record while avoiding secrets or personal data.", ["grafana-dashboards", "obs-telemetry-triage"]),
    ("grafana-query-inspector", "Grafana Query Inspector & Performance", "grafana", "intermediate", "Query Inspector reveals the request sent to a data source, returned data, timing and errors. Use it to distinguish slow queries, empty label matchers, transformations and backend connectivity.", "Inspect rendered PromQL, query step, duration and returned series", "A panel says No Data while the Prometheus expression works in Explore. What do you compare?", "Check dashboard variables, time range, query step, panel transformations, datasource and panel-specific overrides; inspect the actual request in Query Inspector.", ["grafana-panels", "grafana-variables"]),
    ("grafana-library-panels", "Reusable Grafana Library Panels", "grafana", "intermediate", "Library panels let teams maintain one reviewed panel across several dashboards. Version changes and permissions matter because a shared edit can affect many operational views.", "Create a standard service RED row and reuse it across team dashboards", "When is a library panel preferable to copying a panel JSON?", "When the same query, unit, thresholds and links should stay consistent and centrally maintained across dashboards.", ["grafana-dashboards", "grafana-provisioning"]),
    ("grafana-provisioning", "Provision Grafana Dashboards as Code", "grafana", "advanced", "Dashboard JSON or provisioning providers can version dashboards and data sources. Use stable UIDs, review diffs, separate environment-specific datasource settings and understand whether provisioning overwrites UI edits.", "Provision dashboard UID `service-overview` from a reviewed repository file", "A dashboard edit disappears after restart. What likely happened?", "The dashboard is provisioned from a file or provider, so the source of truth overwrote a UI-only edit. Change and review the provisioned definition instead.", ["grafana-datasources", "grafana-library-panels"]),
    ("grafana-no-data", "Grafana No Data, Error & Missing Series", "grafana", "intermediate", "No Data, query errors and a valid zero are different states. Alert behavior must define what happens on no data or execution error so missing telemetry is not mistaken for healthy service behavior.", "No data → pending or separate telemetry-health alert; zero requests → traffic-aware policy", "Why must a no-data alert differ from a zero-value alert?", "No data can mean the exporter or query path is broken, while zero may be a legitimate value; separate telemetry availability from service behavior.", ["grafana-alerts", "prom-absent-up"]),
    ("logstash-multiline", "Parse Multiline Stack Traces Safely", "logs", "advanced", "Multiline codecs combine stack-trace lines into one event and should run at the shipper boundary when possible. Incorrect multiline grouping can merge unrelated events or consume excessive memory.", "Join continuation lines to the preceding timestamped exception event", "Why can multiline parsing be unsafe in a shared Logstash pipeline?", "Events can interleave across streams and get merged incorrectly. Prefer parsing multiline records at the source/shipper with stream-aware boundaries and test concurrency cases.", ["logstash-pipeline", "log-grok"]),
    ("logstash-backpressure", "Logstash Queues, Backpressure & Dead Letters", "logs", "advanced", "Persistent queues buffer events during downstream outages and backpressure slows inputs when capacity fills. Dead-letter queues retain specific indexing failures for later repair; monitor queue size, retries and disk headroom.", "Persistent queue → retry transient Elasticsearch errors → dead-letter mapping rejects", "Elasticsearch is unavailable and Logstash memory is climbing. Which controls help?", "Enable bounded persistent queues, tune batch and retry behavior, ensure inputs respect backpressure, monitor disk and heap, and define recovery behavior for poison events.", ["logstash-pipeline", "elasticsearch-mappings"]),
    ("logstash-mutate", "Logstash Mutate, Date & GeoIP Filters", "logs", "intermediate", "Filters normalize field names, parse timestamps, convert numeric types, add metadata and optionally enrich geography. Keep transformations deterministic and avoid storing sensitive raw values unnecessarily.", "rename `status` → `http.response.status_code`; date `timestamp` → `@timestamp`", "Why should timestamp parsing be tested across time zones and formats?", "Incorrect timezone or format creates shifted event time, making incident searches and correlation misleading; test offsets, missing timezone and malformed timestamps.", ["logstash-pipeline", "elasticsearch-mappings"]),
    ("logstash-conditional-routing", "Logstash Conditional Routing & Branches", "logs", "intermediate", "Conditional filters route events by type, environment or parse status to separate outputs and policies. Keep conditions based on structured fields and provide a fallback route for unknown event types.", "if [event][dataset] == \"nginx.access\" { ... } else { route to quarantine }", "What should happen to an event that matches no known pipeline branch?", "Route it to a bounded quarantine or fallback destination with an observable counter; silently dropping unknown events hides schema changes.", ["logstash-pipeline", "log-grok"]),
    ("ecs-log-schema", "Elastic Common Schema & Field Naming", "logs", "intermediate", "ECS standardizes fields for timestamps, services, hosts, HTTP, users and tracing. Consistent names enable shared Kibana queries and detections across applications and infrastructure.", "service.name, host.name, log.level, trace.id, http.response.status_code", "What improves when teams adopt a common log schema?", "Dashboards, searches, correlations and detections can be reused across services instead of requiring custom field names for every source.", ["log-pipeline", "kibana-kql"]),
    ("elastic-ingest-pipeline", "Elasticsearch Ingest Pipelines", "logs", "intermediate", "Ingest pipelines run processors such as set, rename, grok, date and geoip on documents before indexing. They can share normalization logic, but work should be placed deliberately between shipper and indexer.", "simulate pipeline → parse message → set service.name → index to data stream", "How do you validate an ingest pipeline before changing production indexing?", "Use the simulate API with representative valid, malformed and edge-case documents, inspect each processor result and test the target mapping.", ["logstash-pipeline", "elasticsearch-mappings"]),
    ("elastic-query-dsl", "Elasticsearch Query DSL Basics", "logs", "intermediate", "Query DSL combines bool must, filter, should and must_not clauses. Filter context is cacheable and does not score; use term for exact keyword values and range for dates and numbers.", "bool.filter: term(service.name=checkout), range(@timestamp=last 15m), term(log.level=error)", "Why use filter context for service name and time range?", "These conditions are binary constraints and do not need relevance scoring; filter context is efficient and can be cached.", ["kibana-kql", "elasticsearch-mappings"]),
    ("elastic-shards", "Elasticsearch Shards, Replicas & Capacity", "logs", "advanced", "Primary shards partition an index; replicas add copies for availability and search capacity. Too many tiny shards waste heap and file handles, while oversized shards slow recovery and rebalance.", "Estimate ingest bytes × retention; choose shard count before rollover and monitor shard size", "Why can creating one index per application per day become costly?", "It may create many small shards and cluster metadata overhead. Use data streams, rollover by size/age and a shard strategy based on actual volume.", ["elasticsearch-mappings", "log-pipeline"]),
    ("elastic-ilm", "Index Lifecycle Management Policies", "logs", "intermediate", "ILM moves indices through hot, warm, cold and delete phases using age, size and rollover conditions. Data retention should match operational, privacy and legal requirements and be validated with actual index patterns.", "Roll over at 30 GB or 1 day → warm after 7 days → delete after 30 days", "A delete policy removes logs earlier than expected. What do you inspect?", "Check index creation time, policy phase age, rollover alias/data stream, explain output and whether the policy is attached to the intended template.", ["elasticsearch-mappings", "log-pipeline"]),
    ("kibana-lucene", "Kibana Lucene Query Syntax", "logs", "intermediate", "Lucene syntax supports fielded searches, wildcards and Boolean operators in Kibana when enabled. KQL is often easier for filtering; Lucene is useful for advanced query expressions and scoring behavior.", "service.name:checkout AND (log.level:error OR http.response.status_code:[500 TO 599])", "When should you choose KQL rather than Lucene in Discover?", "Use KQL for readable filtering and field existence; choose Lucene when you need Lucene-specific wildcards, ranges or scoring-oriented query syntax.", ["kibana-kql", "kibana-discover"]),
    ("kibana-runtime-fields", "Kibana Runtime Fields & Data Views", "logs", "advanced", "Data views select index patterns and time fields; runtime fields compute values at query time without reindexing. They are useful for temporary migrations but can increase query cost and should not hide schema debt.", "Create a temporary runtime field to normalize legacy `status_code` to integer", "Why should a heavily used runtime field eventually be indexed at ingest?", "Repeated query-time computation adds cost and can limit aggregations; normalize the field at ingestion once the migration is understood.", ["kibana-kql", "elasticsearch-mappings"]),
    ("kibana-alerting", "Kibana Detection & Log Threshold Rules", "logs", "advanced", "Kibana rules can detect threshold, query, event-count or sequence conditions and route actions through connectors. Schedule, lookback, deduplication, execution gaps and rule permissions affect reliability.", "Alert when 5xx events exceed baseline for service=checkout over 5m", "What prevents a log threshold rule from paging repeatedly on the same incident?", "Use grouping or alert suppression keys, choose a suitable lookback and schedule, and include recovery conditions and an actionable notification owner.", ["kibana-discover", "prom-alertmanager"]),
    ("jaeger-span-tags", "Jaeger Span Attributes, Events & Status", "tracing", "intermediate", "Span attributes describe bounded operation context, events record notable moments and status marks errors. Use semantic conventions and avoid high-cardinality, sensitive or large payload attributes.", "http.request.method=POST · http.response.status_code=503 · error=true", "Where should a database exception be recorded in a trace?", "Set error status and bounded error.type attributes on the database client span; add a concise event while keeping secrets, SQL parameters and personal data out.", ["obs-traces", "jaeger-search"]),
    ("jaeger-service-map", "Jaeger Service Dependency Graphs", "tracing", "intermediate", "Service graphs summarize observed calls between instrumented services and help identify dependency changes. Missing edges can result from sampling, absent instrumentation, context breaks or low traffic.", "checkout → pricing → inventory → postgres", "Why is a service missing from the dependency graph even though it is deployed?", "A graph reflects observed traces, not deployment inventory; verify traffic, instrumentation, sampling, context propagation and service naming.", ["jaeger-search", "obs-traces"]),
    ("trace-baggage", "Trace Context, Baggage & Async Boundaries", "tracing", "advanced", "Trace context links spans; baggage propagates selected key-value context but may cross trust boundaries. Inject/extract context through queues and async jobs while controlling size and data sensitivity.", "Inject traceparent into message headers; extract it when the consumer starts a processing span", "Why should baggage not contain an access token or user email?", "Baggage can propagate to many services and telemetry backends, increasing exposure and cost. Carry only approved, small, non-sensitive routing context.", ["obs-traces", "obs-instrumentation"]),
    ("otel-collector-processors", "OpenTelemetry Collector Receivers & Processors", "signals", "intermediate", "Collector pipelines connect receivers, processors and exporters. Batch, memory limiter, attributes, transform and tail-sampling processors shape telemetry; each component must be enabled in a pipeline to run.", "receivers: otlp → processors: memory_limiter,batch → exporters: otlp/jaeger", "A Collector config lists an exporter but exports nothing. What common configuration is missing?", "The exporter must be referenced by an active traces, metrics or logs service pipeline, and its receiver and processors must also be wired there.", ["obs-instrumentation", "obs-tail-sampling"]),
    ("otel-resource-detection", "OpenTelemetry Resource Attributes", "signals", "intermediate", "Resource attributes identify the entity emitting telemetry and should remain consistent across signals. Set service.name explicitly and use environment or cloud detectors carefully to avoid conflicting duplicate identities.", "service.name=payments-api · service.version=2026.10.18 · deployment.environment=prod", "Why should `service.name` be explicit rather than inferred from a pod name?", "Pod names change on rollout and would split one logical service into many identities; a stable service name supports dashboards, alerts and traces.", ["obs-instrumentation", "ecs-log-schema"]),
    ("otel-semconv", "OpenTelemetry Semantic Conventions", "signals", "intermediate", "Semantic conventions standardize attribute names across HTTP, database, messaging and infrastructure instrumentation. Pin compatible versions and plan migrations when conventions change.", "http.request.method, http.route, server.address, db.system.name", "What problem do semantic conventions solve?", "They let tools and teams interpret common attributes consistently across libraries and services, enabling shared queries and dashboards.", ["obs-instrumentation", "jaeger-span-tags"]),
    ("obs-cardinality-audit", "Audit Telemetry Cost & Cardinality", "signals", "advanced", "Telemetry cost comes from series count, event volume, retention, sample frequency and query work. Audit high-cardinality attributes, oversized logs and low-value traces; apply sampling and retention with an incident use case in mind.", "Break down series by metric and label; compare ingest GB/day by service", "What should be checked before dropping a high-volume metric?", "Confirm whether it supports an SLO, alert, capacity decision or investigation; communicate the owner and replacement signal before removing it.", ["obs-labels", "obs-tail-sampling"]),
    ("obs-privacy", "Telemetry Privacy, Redaction & Access", "signals", "advanced", "Logs and traces can contain credentials, personal data and sensitive URLs. Redact at source or Collector, restrict access by tenant and role, encrypt transport and storage, and define deletion and retention processes.", "Drop authorization and cookie headers; hash approved stable identifiers only when needed", "Why redact at collection rather than relying only on dashboard permissions?", "Sensitive data otherwise persists in indexes, backups, exports and alternate tools; collection-time minimization reduces exposure everywhere downstream.", ["otel-collector-processors", "elasticsearch-mappings"]),
    ("obs-runbook", "Write Alert Runbooks & Ownership", "signals", "basic", "A runbook explains the user impact, first checks, safe mitigations, escalation path and recovery verification for an alert. Assign a team and review links as systems change.", "Alert → dashboard → logs/traces → safe mitigation → owner escalation", "What makes a runbook useful during a page?", "It is short, service-specific, current and actionable; it identifies impact, links to evidence, distinguishes safe from risky changes and names the escalation owner.", ["prom-alerting", "grafana-alerts"]),
    ("obs-blackbox", "Blackbox Probes & Synthetic Monitoring", "signals", "intermediate", "Synthetic probes test user-visible DNS, TLS, HTTP and transaction behavior from an external vantage point. They complement internal metrics by revealing issues before traffic reaches the service.", "Probe DNS → TLS certificate → GET /healthz → assert status and latency", "Why can a blackbox probe fail while application CPU and error metrics look healthy?", "The service process may be healthy inside its network while DNS, certificate, routing, edge policy or an external dependency prevents users from reaching it.", ["prom-scrape-model", "obs-slos"]),
    ("obs-incident-correlation", "Correlate Incidents with Releases & Changes", "signals", "intermediate", "Consistent version labels and deploy annotations let responders compare telemetry before and after a release. Correlation narrows investigation; validate causation with traces, logs and controlled rollback evidence.", "Compare error ratio by service.version and place the rollout revision on dashboard timeline", "A metric regressed immediately after deploy. What evidence supports a causal link?", "Compare affected versions and cohorts, inspect failing traces/logs, verify dependency and traffic changes, and use a safe rollback or canary comparison when practical.", ["grafana-annotations", "obs-telemetry-triage"]),
], "OBS", "Telemetry is a trail of evidence: define the question, write a bounded query, and connect the result to an owner and runbook.")

